-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('celebrating-small-wins', 'Celebrating Small Wins', 'For anyone who finishes something and moves straight to the next thing without a pause. Each day is one small way to notice what went right and let it count, so progress feels real instead of invisible.', 'Motivation', 365, array['Motivation', 'Self-Esteem']::text[], 1, '2026-09-27T17:00:00+00:00'::timestamptz),
  ('easing-perfectionism', 'Easing Perfectionism', 'For people who redo, over-prepare and put things off until they can be flawless. Each day is one small experiment in letting good enough be enough, so you finish more, rest more, and enjoy the work again.', 'Self-Compassion', 365, array['Perfectionism', 'Self-Compassion']::text[], 1, '2026-09-27T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('celebrating-small-wins', 'easing-perfectionism');

