  ('easing-perfectionism', 25, 'Leave the last five percent of a project undone for a day and notice how uncomfortable it feels, then notice that nothing bad happens.'),
  ('easing-perfectionism', 26, 'Make one decision today in under a minute that you would normally research for an hour.'),
  ('easing-perfectionism', 27, 'Wrap a gift quickly, without perfect corners, and give it as it is.'),
  ('easing-perfectionism', 28, 'Notice a moment today when you thought "it is either perfect or a failure" and write down a third option.'),
