  ('easing-perfectionism', 322, 'Rewrite one rule you hold, such as "my house must be spotless for guests," into a gentler one you can actually live by.'),
  ('easing-perfectionism', 323, 'Let a group project have a section that is not up to your standard, and let it belong to the person who wrote it.'),
  ('easing-perfectionism', 324, 'Ask an experienced friend to tell you about their first, terrible attempt at something they are now good at.'),
  ('easing-perfectionism', 325, 'Choose a running, cycling, or swimming pace that is easy enough to keep talking, and hold it the whole way.'),
